/** Textes encore en dur : réglages, aide, nage, coach, plan. */
const LANGS = ["fr", "en", "de", "es", "ja", "nl", "it", "pt", "pt-BR", "sv", "da", "nb", "fi"];

function r(...vals) {
  const out = {};
  LANGS.forEach((lng, i) => { out[lng] = vals[i] ?? vals[1]; });
  return out;
}

